        "data science": 2.0,
        "computer science": 2.0
    }

    # Initialize the total score
    total_score = 0.0

    # Evaluate each attribute
    for attribute, score in attribute_scores.items():
        if attribute in ["income", "parents_degree"]:
            total_score += attribute_scores[attribute][applicant.__getattribute__(attribute)]
        else:
            total_score += attribute_scores[attribute] * applicant.__getattribute__(attribute)

    # Evaluate the skills
